mapper.update:
UPDATE activity_usage_period SET used_count = used_count + 1
WHERE user_id = #{userId} AND activity_id = #{activityId}
  AND period_type = #{periodType} AND period_key = #{periodKey}
  AND (#{limit} = -1 OR used_count < #{limit})

UPDATE activity_usage_period SET used_count = used_count - 1
WHERE user_id = #{userId} AND activity_id = #{activityId}
  AND period_type = #{periodType} AND period_key = #{periodKey}
  AND used_count > 0
